          "stepId": "deck-brief",
          "name": "Brief the squad on deck — the morning, who is in which lane",
          "task": "coach",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "programStart" }
        },
        {
          "stepId": "watch-warmup",
          "name": "Watch the warm-up from the deck, fix anything ugly",
          "task": "coach",
          "duration": { "type": "fixed", "seconds": 900 },
          "startTrigger": { "type": "afterStep", "stepId": "deck-brief" }
        },
        {
          "stepId": "whiteboard",
          "name": "Call the lanes to the wall and walk the main set on the whiteboard — nobody pushes off until the board is done",
          "task": "coach",
          "duration": { "type": "fixed", "seconds": 300 },
          "startTrigger": { "type": "afterStep", "stepId": "wu1" }
        },
        {
          "stepId": "time-sprints",
          "name": "Time the sprints from the deck — stopwatch and the wall clock",
          "task": "coach",
          "duration": { "type": "fixed", "seconds": 1800 },
          "startTrigger": {
            "type": "compound",
            "logic": "all",
            "triggers": [
              { "type": "afterStep", "stepId": "main1" },
              { "type": "afterStep", "stepId": "main2" },
              { "type": "afterStep", "stepId": "main3" }
            ]
          }
        },
        {
          "stepId": "debrief",
          "name": "Deck debrief — splits, what to fix, Saturday's meet",
          "task": "coach",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "cd1" }
        }
      ]
    },
    {
      "trackId": "lane1",
      "name": "Lane 1 — Sprint group",
      "steps": [
        {
          "stepId": "wu1",
          "name": "Warm-up (all three lanes together) — 800 easy, mixed stroke, breathing every five on the last hundred",
          "task": "lane",
          "duration": { "type": "fixed", "seconds": 1200 },
          "startTrigger": { "type": "afterStep", "stepId": "deck-brief" }
        },
        {
          "stepId": "kick1",
          "name": "Kick set with boards",
          "task": "lane",
          "duration": { "type": "fixed", "seconds": 1200 },
          "startTrigger": { "type": "afterStep", "stepId": "whiteboard" }
        },
        {
          "stepId": "main1",
          "name": "Main set — lane 1, plan 40 minutes (30–50)",
          "task": "lane",
          "duration": { "type": "variable", "minSeconds": 1800, "maxSeconds": 3000, "defaultSeconds": 2400 },
          "startTrigger": { "type": "afterStep", "stepId": "kick1" }
        },
        {
          "stepId": "cd1",
          "name": "Cooldown (all lanes together) — 300 easy backstroke and breaststroke",
          "task": "lane",
          "duration": { "type": "fixed", "seconds": 600 },
          "startTrigger": { "type": "afterStep", "stepId": "sprint", "instances": "all" }
        }
      ]
    },
    {
      "trackId": "lane2",
      "name": "Lane 2 — Middle distance",
      "steps": [
        {
          "stepId": "wu2",
          "name": "Warm-up (all three lanes together) — 800 easy, mixed stroke, breathing every five on the last hundred",
          "task": "lane",
          "duration": { "type": "fixed", "seconds": 1200 },
          "startTrigger": { "type": "afterStep", "stepId": "deck-brief" }
        },
        {
          "stepId": "kick2",
          "name": "Kick set with boards",
          "task": "lane",
          "duration": { "type": "fixed", "seconds": 1200 },
          "startTrigger": { "type": "afterStep", "stepId": "whiteboard" }
        },
        {
          "stepId": "main2",
          "name": "Main set — lane 2, plan 45 minutes (30–50)",
          "task": "lane",
          "duration": { "type": "variable", "minSeconds": 1800, "maxSeconds": 3000, "defaultSeconds": 2700 },
          "startTrigger": { "type": "afterStep", "stepId": "kick2" }
        },
        {
          "stepId": "cd2",
          "name": "Cooldown (all lanes together) — 300 easy backstroke and breaststroke",
          "task": "lane",
          "duration": { "type": "fixed", "seconds": 600 },
