          "task": "lane",
          "duration": { "type": "variable", "minSeconds": 1800, "maxSeconds": 3000, "defaultSeconds": 3000 },
          "startTrigger": { "type": "afterStep", "stepId": "kick3" }
        },
        {
          "stepId": "cd3",
          "name": "Cooldown (all lanes together) — 300 easy backstroke and breaststroke",
          "task": "lane",
          "duration": { "type": "fixed", "seconds": 600 },
