      "name": "Starting blocks — one set, one lane at a time",
      "steps": [
        {
          "stepId": "sprint",
          "name": "Sprint set — 10 minutes per lane off the blocks, 25s flat out, lane 1 → lane 2 → lane 3 (lane 3 gets the extra rest while the first two go)",
          "task": "blocks",
          "duration": { "type": "fixed", "seconds": 600 },
          "replicates": { "count": 3, "mode": "serial" },
          "startTrigger": {
            "type": "compound",
            "logic": "all",
