  "resourceConstraints": [
    { "task": "lane", "maxConcurrent": 3 },
    { "task": "blocks", "maxConcurrent": 1 },
    { "task": "coach", "maxConcurrent": 1 }
  ],
  "metadata": {
    "serves": "12 swimmers, 1 coach",
    "sourceUrl": "",
    "attribution": "Thursday AM practice plan — three lanes, 2h30m pool time"
  }
